import { run } from './hackonctl.js'

async function main(): Promise<void> {
  const exitCode = await run(process.argv)
  process.exit(exitCode)
}

main().catch((error: unknown) => {
  if (error instanceof Error) {
    console.error(error.message)
  } else {
    console.error(error)
  }
  process.exit(1)
})
